package com.gameaggregator.webhookservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="webhook_endpoints") public class WebhookEndpoint{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID tenantId;@Column(nullable=false)public String url;@Lob @Column(nullable=false)public String encryptedSecret;@Lob @Column(nullable=false)public String eventSubscriptionsJson;@Column(nullable=false)public String environment;@Column(nullable=false)public boolean active=true;@Column(nullable=false)public int timeoutMs;@Column(nullable=false)public int maxRetries;@Version public long revision;protected WebhookEndpoint(){}public WebhookEndpoint(UUID t,String u,String s,String e,String n,int o,int r){tenantId=t;url=u;encryptedSecret=s;eventSubscriptionsJson=e;environment=n;timeoutMs=o;maxRetries=r;}}